'use strict';
/**
 * fact-validator.js — extract factual claims from a generated reading and
 * validate each against the computed chart.
 *
 * Purpose (ADR 0001 prerequisite): a reading is prose generated by a model.
 * Its interpreterive content cannot be verified, but its *factual* content can.
 * This module finds the checkable claims and returns a verdict per claim, so a
 * judge (or the pipeline) can reject readings that misrepresent the chart.
 *
 * Rule: only claims traceable to the chart are facts. Anything else is
 * interpretation and is reported separately, never as a failure.
 */

const { chart } = require('./bazi.js');
const T = require('./bazi-tables.js');

const ALL_GAN = T.GAN;
const ALL_ZHI = T.ZHI;
const ALL_WUXING = ['木','火','土','金','水'];
const ALL_GODS = ['比肩','劫财','食神','伤官','偏财','正财','七杀','正官','偏印','正印'];

/** Parse the pillars out of a chart for comparison. */
function chartFacts(dateStr, timeStr, opts = {}) {
  const c = chart(dateStr, timeStr, opts);
  const p = c.pillars;
  const year = opts.year || Number(String(dateStr).slice(0, 4));

  // Timing layers, computed here so the checker can verify claims the segmented
  // reading makes about periods (today / this year / the current decade).
  let todayPillar = null, annualPillarV = null;
  try { todayPillar = require('./luck-pillars.js').dailyPillar(dateStr).dayGanZhi; } catch {}
  try { annualPillarV = require('./luck-pillars.js').annualPillar(year).ganZhi; } catch {}

  const T2 = require('./bazi-tables.js');
  const dm = c.tenGods.dayMaster;
  const timing = {
    date: dateStr,
    year,
    todayPillar,
    todayRelation: todayPillar ? T2.tenGod(dm, todayPillar[0]) : null,
    annualPillar: annualPillarV,
    annualRelation: annualPillarV ? T2.tenGod(dm, annualPillarV[0]) : null,
    decadePillar: null,
    decadeRelation: null,
  };

  return {
    raw: c,
    pillars: p,
    pillarList: [p.year, p.month, p.day, p.hour],
    dayMaster: c.tenGods.dayMaster,
    stems: c.tenGods.stems,
    branches: c.tenGods.branches,
    elements: c.elements,
    branchZhi: [p.year[1], p.month[1], p.day[1], p.hour[1]],
    branchRelations: T.branchRelations([p.year[1], p.month[1], p.day[1], p.hour[1]]),
    timing,
  };
}

/**
 * Extract pillar-shaped tokens from text.
 * Accepts Chinese characters (庚申 己卯 丁亥 乙巳) and romanized pinyin
 * (Geng Shen Ji Mao Ding Hai Yi Si), since a model may transliterate.
 */
const PINYIN_GAN = {
  甲:'jia', 乙:'yi', 丙:'bing', 丁:'ding', 戊:'wu',
  己:'ji', 庚:'geng', 辛:'xin', 壬:'ren', 癸:'gui',
};
const PINYIN_ZHI = {
  子:'zi', 丑:'chou', 寅:'yin', 卯:'mao', 辰:'chen', 巳:'si',
  午:'wu', 未:'wei', 申:'shen', 酉:'you', 戌:'xu', 亥:'hai',
};

function findPillarClaims(text) {
  if (!text) return [];
  const out = [];

  // 1. Chinese characters: four consecutive stem+branch pairs.
  const cls = `[${ALL_GAN.join('')}][${ALL_ZHI.join('')}]`;
  const re = new RegExp(`${cls}(?:[\\s,，、|/]+${cls}){3}`, 'g');
  let m;
  while ((m = re.exec(text)) !== null) out.push(m[0].replace(/[\s,，、|/]+/g, ' ').trim());

  // 2. Romanized: four consecutive pinyin stem+branch pairs.
  const ganAlt = Object.values(PINYIN_GAN).join('|');
  const zhiAlt = Object.values(PINYIN_ZHI).join('|');
  const pair = `(?:${ganAlt})[\\s-]*(?:${zhiAlt})`;
  const reRo = new RegExp(`${pair}(?:[\\s,，、|/]+${pair}){3}`, 'gi');
  while ((m = reRo.exec(text)) !== null) {
    // Convert back to characters so it can be compared to the chart.
    const words = m[0].toLowerCase().match(new RegExp(`${ganAlt}|${zhiAlt}`, 'g')) || [];
    if (words.length === 8) {
      const ganOf = Object.fromEntries(Object.entries(PINYIN_GAN).map(([k,v])=>[v,k]));
      const zhiOf = Object.fromEntries(Object.entries(PINYIN_ZHI).map(([k,v])=>[v,k]));
      const pairs = [];
      for (let i = 0; i < 8; i += 2) pairs.push((ganOf[words[i]]||'?') + (zhiOf[words[i+1]]||'?'));
      out.push(pairs.join(' '));
    }
  }
  return [...new Set(out)];
}

/**
 * Find element-dominance claims, in both Chinese and English phrasing.
 * Handles: "Fire is dominant", "dominated by Wood", "Fire is strongest",
 * "strong presence of Metal", "you are Fire-dominant".
 */
function findDominanceClaims(text) {
  if (!text) return [];
  const map = {
    wood:'木', fire:'火', earth:'土', metal:'金', water:'水',
  };
  const ZH = ['木','火','土','金','水'];
  const en = '(wood|fire|earth|metal|water)';
  const zh = '([木火土金水])';
  const out = [];

  const patterns = [
    // Chinese
    new RegExp(`${zh}\\s*(?:is\\s+)?(?:dominant|strongest|most\\s+prominent)`, 'gi'),
    new RegExp(`(?:dominant|dominance|strongest|dominated\\s+by|abundance\\s+of|strong\\s+presence\\s+of|plenty\\s+of)\\s*${zh}`, 'gi'),
    // English element words, both orders
    new RegExp(`${en}\\s*(?:is\\s+)?(?:dominant|strongest|most\\s+prominent)`, 'gi'),
    new RegExp(`(?:dominant|dominance|strongest|dominated\\s+by|abundance\\s+of|strong\\s+presence\\s+of|plenty\\s+of)\\s*(?:the\\s+)?${en}`, 'gi'),
    new RegExp(`(?:you\\s+are|is|are)\\s+${en}\\s*[- ]?dominant`, 'gi'),
  ];
  for (const re of patterns) {
    let m;
    while ((m = re.exec(text)) !== null) {
      const tok = m[1];
      const el = ZH.includes(tok) ? tok : map[tok.toLowerCase()];
      if (el) out.push(el);
    }
  }
  return [...new Set(out)];
}

/** Find day-master claims such as "your day master is 丁" or "Yin Fire day master". */
function findDayMasterClaims(text) {
  if (!text) return [];
  const out = [];
  // explicit gan reference near "day master"
  const re1 = /day\s*master\s*(?:is|:)?\s*([甲乙丙丁戊己庚辛壬癸])/gi;
  let m;
  while ((m = re1.exec(text)) !== null) out.push({ kind: 'gan', value: m[1] });
  // elemental day master: "Yin Fire day master", "Yang Metal day master"
  const elMap = {
    wood:'木', fire:'火', earth:'土', metal:'金', water:'水',
  };
  const re2 = /\b(yin|yang)\s+(wood|fire|earth|metal|water)\s+(?:day\s*master|daymaster|day\s+master)/gi;
  while ((m = re2.exec(text)) !== null) {
    const yang = m[1].toLowerCase() === 'yang';
    const el = elMap[m[2].toLowerCase()];
    // which gan has this element + polarity?
    const candidates = ALL_GAN.filter(g => T.GAN_WUXING[g] === el && T.GAN_YANG[g] === yang);
    out.push({ kind: 'elemental', value: el, yang, candidates });
  }
  return out;
}

/** Find explicit Ten Gods mentions. */
function findTenGodClaims(text) {
  if (!text) return [];
  const out = [];
  for (const g of ALL_GODS) if (text.includes(g)) out.push(g);
  return out;
}

/**
 * Validate a reading against a chart.
 * Returns { claims, failures, verdict } where verdict is 'pass' | 'fail' | 'no-claims'.
 */
function validateReading(text, dateStr, timeStr, opts = {}) {
  const facts = chartFacts(dateStr, timeStr, opts);
  const claims = [];
  const failures = [];

  // 1. Pillar strings
  for (const claimed of findPillarClaims(text)) {
    const ok = facts.pillarList.some(p => {
      const pair = [p[0], p[1]].join('');
      return claimed.replace(/\s+/g, '').includes(facts.pillarList.map(x=>x).join('')) ||
             facts.pillarList.join(' ') === claimed;
    });
    const exact = facts.pillarList.join(' ') === claimed;
    claims.push({ type: 'pillars', claimed, ok: exact });
    if (!exact) failures.push({ type: 'pillars', claimed, expected: facts.pillarList.join(' ') });
  }

  // 2. Day master
  for (const dm of findDayMasterClaims(text)) {
    if (dm.kind === 'gan') {
      const ok = dm.value === facts.dayMaster;
      claims.push({ type: 'dayMaster', claimed: dm.value, ok });
      if (!ok) failures.push({ type: 'dayMaster', claimed: dm.value, expected: facts.dayMaster });
    } else {
      const expectedGan = facts.dayMaster;
      const ok = dm.candidates.includes(expectedGan);
      claims.push({ type: 'dayMaster', claimed: `${dm.yang?'Yang':'Yin'} ${dm.value}`, ok });
      if (!ok) failures.push({
        type: 'dayMaster',
        claimed: `${dm.yang?'Yang':'Yin'} ${dm.value}`,
        expected: `${T.GAN_YANG[expectedGan]?'Yang':'Yin'} ${T.GAN_WUXING[expectedGan]} (${expectedGan})`,
      });
    }
  }

  // 3. Element dominance — must match the actual strongest element.
  const strongest = Object.entries(facts.elements.raw)
    .sort((a, b) => b[1] - a[1])[0][0];
  for (const el of findDominanceClaims(text)) {
    const ok = el === strongest;
    claims.push({ type: 'dominance', claimed: el, ok });
    if (!ok) failures.push({ type: 'dominance', claimed: el, expected: strongest });
  }

  // 4. Ten Gods — only flag a claim if the god is absent from the whole chart.
  const presentGods = new Set();
  Object.values(facts.stems).forEach(g => presentGods.add(g));
  Object.values(facts.branches).forEach(arr => arr.forEach(g => presentGods.add(g)));
  for (const g of findTenGodClaims(text)) {
    const ok = presentGods.has(g);
    claims.push({ type: 'tenGod', claimed: g, ok, note: 'god may be interpreted, not enumerated' });
    // Ten God mentions are soft: a reading may legitimately describe a god
    // conceptually. Record but do not hard-fail unless the god is absent.
    if (!ok) failures.push({ type: 'tenGod', claimed: g, expected: [...presentGods].join('/') });
  }

  const verdict = claims.length === 0 ? 'no-claims' : (failures.length ? 'fail' : 'pass');
  return { dateStr, timeStr, facts: {
    pillars: facts.pillarList.join(' '),
    dayMaster: facts.dayMaster,
    strongestElement: strongest,
    godsPresent: [...presentGods],
  }, claims, failures, verdict };
}

module.exports = { validateReading, chartFacts, findPillarClaims, findDominanceClaims, findDayMasterClaims, findTenGodClaims };

if (require.main === module) {
  // smoke: a correct reading should pass, a corrupted one should fail
  const good = 'Your day master is Ding, a Yin Fire day master. Your four pillars are Geng Shen Ji Mao Ding Hai Yi Si. Fire is dominant in your chart.';
  const bad  = 'Your day master is Geng, a Yang Metal day master. Fire is dominant in your chart.';
  console.log('--- honest reading (should pass) ---');
  console.log(JSON.stringify(validateReading(good, '1980-03-15', '09:20'), null, 2));
  console.log('--- corrupted reading (should fail) ---');
  console.log(JSON.stringify(validateReading(bad, '1980-03-15', '09:20'), null, 2));
}
